#!/usr/bin/env python3
"""
World Talk Brief (WTB Studio V91) — Self-Contained 4-Format Global News & Documentary Engine.
Automatically unpacks the modular `studio/` package, 208-country Natural Earth cartography (`world_atlas.py`),
`studio_config.json`, `requirements.txt`, and `tests/` on first run so updating `wtb_engine.py` and
`.github/workflows/test_and_run.yml` on GitHub works out of the box with zero manual folder setup!

4 Supported Broadcast Styles (--style auto|bbc_dispatch|think_school|nitish_rajput|abhi_niyu):
  1. bbc_dispatch   : BBC World News style breaking global dispatch
  2. think_school   : Think School style geopolitical & economic strategy case study
  3. nitish_rajput  : Nitish Rajput style forensic investigation & red-thread evidence dossier
  4. abhi_niyu      : Abhi & Niyu style human impact & solution explainer
"""
import base64
import json
import os
import sys
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent

_V91_STUDIO_BUNDLE_B64 = ""


def bootstrap_studio_files(force_update=True):
    """Unpacks/updates the V91 `studio/` modules, `tests/`, `studio_config.json`, and `requirements.txt`."""
    payload = json.loads(zlib.decompress(base64.b64decode(_V91_STUDIO_BUNDLE_B64)).decode("utf-8"))
    for rel_path, content in payload.items():
        target = ROOT / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        if force_update or not target.exists():
            target.write_text(content, encoding="utf-8")


bootstrap_studio_files(force_update=True)

if __name__ == "__main__":
    if "--bootstrap" in sys.argv:
        print("✅ WTB Studio V91 modules, 208-country atlas, config, and tests unpacked successfully!")
        raise SystemExit(0)
    from studio.pipeline import main
    raise SystemExit(main())
